 "content": "def transform(grid):
    """Extend the diagonal pattern by period inferred from the gap between clue runs."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    # For colored clue cells, use the strongest diagonal family.
    dr, dl = {}, {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                dr.setdefault(c-r, []).append(color)
                dl.setdefault(c+r, []).append(color)
    use_left = max(map(len, dl.values()), default=0) > max(map(len, dr.values()), default=0)
    groups = dl if use_left else dr
    clues = {pos: max(set(colors), key=colors.count) for pos, colors in groups.items()}

    # These objects encode contiguous color bands along diagonal coordinates.
    # Infer cycle by the full observed span; unobserved coordinates between
    # clue bands are assigned from the repeated band motif (here 7 then 9).
    lo, hi = min(clues), max(clues)
    period = hi - lo + 1
    band = [None] * period
    for pos, color in clues.items():
        band[pos-lo] = color
    # Extend bands using nearest observed color in the same left-to-right run.
    for i in range(period):
        if band[i] is None:
            before = [j for j in range(i-1, -1, -1) if band[j] is not None]
            after = [j for j in range(i+1, period) if band[j] is not None]
            band[i] = band[before[0]] if before else band[after[0]]
    # The clue examples show this diagonal color motif repeats with the
    # smallest complete period that preserves all clue colors.
    for p in range(1, period+1):
        ok = True
        candidate = band[:p]
        for pos, color in clues.items():
            if candidate[(pos-lo) % p] != color:
                ok = False
                break
        if ok:
            band, period = candidate, p
            break

    if use_left:
        return [[band[(r+c-lo) % period] for c in range(w)] for r in range(h)]
    return [[band[(c-r-lo) % period] for c in range(w)] for r in range(h)]


if __name__ == "__main__":
    test = [[int(x) for x in line.split()] for line in open("/tmp/test_grid.txt")]
    result = transform(test)
    assert len(result) == 20 and all(len(row) == 20 for row in result)
    print(result)
