 "content": "def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    # Horizontal stripe demos: choose the observed repeating stripe sequence.
    rows = {r: row[0] for r, row in enumerate(grid)
            if row and row[0] != 0 and all(x == row[0] for x in row)}
    if rows:
        period = len(rows)
        cycle = {r % period: color for r, color in rows.items()}
        # If stripe clues are sparse, use the simple cycle that reproduces the
        # observed indexed samples, carrying the prior stripe into gaps.
        for i in range(period):
            if i not in cycle:
                prev = [j for j in cycle if j < i]
                cycle[i] = cycle[prev[-1] if prev else max(cycle)]
        return [[cycle[r % period] for _ in range(w)] for r in range(h)]

    # Diagonal clue tracks: choose the line direction with the most marks.
    dr, dl = {}, {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                dr.setdefault(c-r, []).append(value)
                dl.setdefault(c+r, []).append(value)
    use_plus = max(map(len, dl.values()), default=0) > max(map(len, dr.values()), default=0)
    lines = dl if use_plus else dr
    samples = {pos: max(set(values), key=values.count) for pos, values in lines.items()}

    # In the diagonal examples, two parallel lines have same color and repeat
    # with a constant run width; infer run width from all matching coordinates.
    # Search small periods and prefer the one producing the least alternation.
    candidates = []
    for period in range(1, 2 * len(samples) + 3):
        cycle = {}
        valid = True
        for pos, color in samples.items():
            residue = pos % period
            if residue in cycle and cycle[residue] != color:
                valid = False
                break
            cycle[residue] = color
        if valid:
            candidates.append((period, cycle))
    if not candidates:
        raise ValueError("No cycle consistent with diagonal samples")
    period, cycle = candidates[0]
    # Complete absent cycle positions by repeating the nearest previous run.
    known = sorted(cycle)
    for residue in range(period):
        if residue not in cycle:
            prior = [k for k in known if k < residue]
            cycle[residue] = cycle[prior[-1] if prior else known[-1]]
    if use_plus:
        return [[cycle[(r+c) % period] for c in range(w)] for r in range(h)]
    return [[cycle[(c-r) % period] for c in range(w)] for r in range(h)]


if __name__ == '__main__':
    demo = [[0,2,0,3,0],[5,0,2,0,3],[0,5,0,2,0],[0,0,5,0,2],[0,0,0,5,0]]
    assert transform(demo) == [[3,2,5,3,2],[5,3,2,5,3],[2,5,3,2,5],[3,2,5,3,2],[5,3,2,5,3]]
    test = [[int(x) for x in line.split()] for line in open('/tmp/test_grid.txt')]
    out = transform(test)
    assert len(out) == 20 and all(len(row) == 20 for row in out)
    print(out)
