 "content": "def transform(grid):
    """Complete periodic row/diagonal stripes from their color clues."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    # Full-width stripe clues: number of marked rows is the cycle length.
    stripe_samples = {
        r: row[0]
        for r, row in enumerate(grid)
        if row[0] != 0 and all(value == row[0] for value in row)
    }
    if stripe_samples:
        period = len(stripe_samples)
        cycle = {r % period: color for r, color in stripe_samples.items()}
        if len(cycle) != period:
            raise ValueError("Stripe clues do not determine a complete cycle")
        return [[cycle[r % period] for _ in range(w)] for r in range(h)]

    # Sparse stripe clues run along one of the two diagonal directions.
    down_right = {}  # constant column - row
    down_left = {}   # constant column + row
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color != 0:
                down_right.setdefault(c - r, []).append(color)
                down_left.setdefault(c + r, []).append(color)

    use_down_left = max((len(v) for v in down_left.values()), default=0) > max(
        (len(v) for v in down_right.values()), default=0
    )
    lines = down_left if use_down_left else down_right
    samples = {}
    for position, colors in lines.items():
        # Every clue diagonal carries a single stripe color.
        counts = {color: colors.count(color) for color in set(colors)}
        samples[position] = max(counts, key=counts.get)

    # One sample per distinct diagonal determines the repeating cycle length.
    period = len(samples)
    cycle = {position % period: color for position, color in samples.items()}
    if len(cycle) != period:
        raise ValueError("Diagonal clues do not determine a complete cycle")

    if use_down_left:
        return [[cycle[(r + c) % period] for c in range(w)] for r in range(h)]
    return [[cycle[(c - r) % period] for c in range(w)] for r in range(h)]


if __name__ == "__main__":
    # Demo 3 diagonal regression.
    d3 = [[0,2,0,3,0],[5,0,2,0,3],[0,5,0,2,0],[0,0,5,0,2],[0,0,0,5,0]]
    o3 = [[3,2,5,3,2],[5,3,2,5,3],[2,5,3,2,5],[3,2,5,3,2],[5,3,2,5,3]]
    assert transform(d3) == o3
    # Demo 7 diagonal regression.
    d7 = [[0,1,0,0,6,5,0],[1,0,0,6,5,0,0],[0,0,6,5,0,0,4],
          [0,6,5,0,0,4,0],[6,5,0,0,4,0,0],[5,0,0,4,0,0,0],[0,0,4,0,0,0,3]]
    o7 = [[5,1,3,4,6,5,1],[1,3,4,6,5,1,3],[3,4,6,5,1,3,4],
          [4,6,5,1,3,4,6],[6,5,1,3,4,6,5],[5,1,3,4,6,5,1],[1,3,4,6,5,1,3]]
    assert transform(d7) == o7
    # The full-width stripe examples are checked against exact saved fixtures.
    for ip, op in (("/tmp/demo5.txt", "/tmp/demo5out.txt"),
                   ("/tmp/demo6.txt", "/tmp/demo6out.txt")):
        grid = [[int(x) for x in line.split()] for line in open(ip)]
        expected = [[int(x) for x in line.split()] for line in open(op)]
        assert transform(grid) == expected
    test = [[int(x) for x in line.split()] for line in open("/tmp/test_grid.txt")]
    result = transform(test)
    assert len(result) == len(test) and all(len(row) == len(test[0]) for row in result)
    print(result)
    print("Demo 3, 5, 6, and 7 exact checks passed; test dimensions are valid")
