 "content": "def _periodic_fill(samples):
    """Infer the shortest periodic stripe cycle consistent with all clues."""
    for period in range(1, 2 * len(samples) + 2):
        known = {}
        for position, color in samples.items():
            residue = position % period
            if residue in known and known[residue] != color:
                break
            known[residue] = color
        else:
            cycle = dict(known)
            positions = sorted(cycle)
            for residue in range(period):
                if residue not in cycle:
                    earlier = [p for p in positions if p < residue]
                    cycle[residue] = cycle[earlier[-1] if earlier else positions[-1]]
            return period, cycle
    raise ValueError("No period matches all stripe clues")


def transform(grid):
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    # Fully colored horizontal rows are sampled points of a periodic row cycle.
    stripes = {r: row[0] for r, row in enumerate(grid)
               if row[0] != 0 and all(value == row[0] for value in row)}
    if stripes:
        period, cycle = _periodic_fill(stripes)
        return [[cycle[r % period] for _ in range(w)] for r in range(h)]

    # Otherwise the clues belong to parallel diagonal stripes.
    down_right, down_left = {}, {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                down_right.setdefault(c-r, []).append(color)
                down_left.setdefault(c+r, []).append(color)
    use_down_left = max((len(v) for v in down_left.values()), default=0) > max(
        (len(v) for v in down_right.values()), default=0)
    groups = down_left if use_down_left else down_right
    samples = {position: max(set(colors), key=colors.count)
               for position, colors in groups.items()}
    period, cycle = _periodic_fill(samples)
    if use_down_left:
        return [[cycle[(r+c) % period] for c in range(w)] for r in range(h)]
    return [[cycle[(c-r) % period] for c in range(w)] for r in range(h)]


