    demo3 = [[0,2,0,3,0],[5,0,2,0,3],[0,5,0,2,0],[0,0,5,0,2],[0,0,0,5,0]]
    output3 = [[3,2,5,3,2],[5,3,2,5,3],[2,5,3,2,5],[3,2,5,3,2],[5,3,2,5,3]]
    assert transform(demo3) == output3
    demo7 = [[0,1,0,0,6,5,0],[1,0,0,6,5,0,0],[0,0,6,5,0,0,4],
             [0,6,5,0,0,4,0],[6,5,0,0,4,0,0],[5,0,0,4,0,0,0],[0,0,4,0,0,0,3]]
    output7 = [[5,1,3,4,6,5,1],[1,3,4,6,5,1,3],[3,4,6,5,1,3,4],
               [4,6,5,1,3,4,6],[6,5,1,3,4,6,5],[5,1,3,4,6,5,1],[1,3,4,6,5,1,3]]
    assert transform(demo7) == output7
    for ip, op in (("/tmp/demo5.txt", "/tmp/demo5out.txt"),
                   ("/tmp/demo6.txt", "/tmp/demo6out.txt")):
        grid = [[int(x) for x in line.split()] for line in open(ip)]
        expected = [[int(x) for x in line.split()] for line in open(op)]
        assert transform(grid) == expected
    test = [[int(x) for x in line.split()] for line in open("/tmp/test_grid.txt")]
    out = transform(test)
    assert len(out) == len(test) and all(len(row) == len(test[0]) for row in out)
