        for position, color in samples.items():
            residue = position % period
            if residue in cycle and cycle[residue] != color:
                consistent = False
                break
            cycle[residue] = color
        if consistent:
            # For the demonstrated tasks, the shortest viable period has every
            # residue sampled; a sparse residue set cannot determine a unique fill.
            if len(cycle) == period:
                return period, cycle
    raise ValueError("Clue samples do not determine a complete periodic cycle")


def transform(grid):
    """Extend the periodic stripe pattern indicated by sparse colored clues."""
    h = len(grid)
    w = len(grid[0]) if h else 0
    if not h or not w:
        return [row[:] for row in grid]

    # Horizontal full-width stripes sample a cycle over row indices.
    row_samples = {
        r: row[0]
        for r, row in enumerate(grid)
        if row[0] != 0 and all(value == row[0] for value in row)
    }
    if row_samples:
        period, cycle = _infer_cycle(row_samples)
        return [[cycle[r % period] for _ in range(w)] for r in range(h)]

    # Otherwise, group nonzero clues by both diagonal invariants.
    down_right = {}  # constant c-r
    down_left = {}   # constant c+r
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                down_right.setdefault(c - r, []).append(color)
                down_left.setdefault(c + r, []).append(color)

    # The intended orientation has the longest repeated clue diagonals.
    use_down_left = max((len(v) for v in down_left.values()), default=0) > max(
        (len(v) for v in down_right.values()), default=0
    )
    lines = down_left if use_down_left else down_right
    samples = {}
    for position, colors in lines.items():
        if len(set(colors)) != 1:
            raise ValueError("Conflicting colors on one clue diagonal")
        samples[position] = colors[0]

    period, cycle = _infer_cycle(samples)
    if use_down_left:
        return [[cycle[(r + c) % period] for c in range(w)] for r in range(h)]
    return [[cycle[(c - r) % period] for c in range(w)] for r in range(h)]


